	if counts[StatusSettled] != 1 {
		t.Fatalf("settled=%d want exactly 1 (counts=%v)", counts[StatusSettled], counts)
	}
	if counts[StatusFunds] != n-1 {
		t.Fatalf("insufficient=%d want %d (counts=%v)", counts[StatusFunds], n-1, counts)
	}
}

