1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math/big"
9		"sort"
10	)
11	
12	// 离线流水对账：把外部支付渠道提供的有序流水与本地账本逐笔核对。
13	// 对账是只读操作，不改变余额、历史或账本文件。
14	//
15	// 逐条结果（保持输入顺序）有五种：
16	//   - matched：编号命中一条成功记录，且全部核对字段一致；
17	//   - field_mismatch：编号命中成功记录，但至少一个字段不同（逐个列出差异）；
18	//   - missing_in_ledger：账本中没有该编号的成功记录；
19	//   - duplicate：同一(kind,id)在输入中出现多次，整组全部标为重复并附全部
20	//     输入位置，不再判断字段差异，也不再把对应账本记录列为缺失；
21	//   - out_of_scope：命中同类型同编号的成功记录，但该记录的成功序号不在本次
22	//     核对范围内（after < seq <= through）。不比较字段、不计入流水侧汇总；
23	//     该编号在流水中出现多次时全部按此状态处理（优先于整组重复）。
24	//
25	// 付款编号与退款编号分别匹配，同名也不会混为一笔。只核对成功记录：
26	// 已退款的付款仍按原扣款核对，退款单独核对。账本中没有任何对应流水的入选
27	// 记录另列缺失（先按付款成功顺序，再按退款成功顺序）。范围只影响记录是否
28	// 参加核对，不切断关联：入选退款仍可指向范围外付款，入选付款仍携带范围外
29	// 退款的信息。
30	
31	const (
32		ReconMatched         = "matched"
33		ReconFieldMismatch   = "field_mismatch"
34		ReconMissingInLedger = "missing_in_ledger"
35		ReconDuplicate       = "duplicate"
36		ReconOutOfScope      = "out_of_scope"
37	)
38	
39	// amountJSON 是必须提供、且为 int64 整数的金额。
40	// 使用指针 + 自定义解码区分“缺省/null/非数字/越界”等情形。
41	type amountJSON struct {
42		v int64
43	}
44	
45	func (a *amountJSON) UnmarshalJSON(data []byte) error {
46		if string(data) == "null" {
47			return fmt.Errorf("amount must be an int64 integer, not null")
48		}
49		dec := json.NewDecoder(bytes.NewReader(data))
50		var v int64
51		if err := dec.Decode(&v); err != nil {
52			return err
53		}
54		// 单个数字字面量必须恰好结束。
55		if tok, err := dec.Token(); err != io.EOF {
56			if err == nil {
57				return fmt.Errorf("invalid integer amount (unexpected token %v)", tok)
58			}
59			return err
60		}
61		a.v = v
62		return nil
63	}
64	
65	// flowEntryJSON 是流水的严格解码形态。未知字段按标准库惯例忽略。
66	type flowEntryJSON struct {
67		Kind         string      `json:"kind"`
68		ID           string      `json:"id"`
69		Account      string      `json:"account"`
70		Asset        string      `json:"asset"`
71		Amount       *amountJSON `json:"amount"`
72		Fee          *amountJSON `json:"fee"`
73		Charged      *amountJSON `json:"charged"`
74		SettlementID string      `json:"settlement_id"`
75	}
76	
77	// flowRequestJSON 是对账输入：{"entries":[...]}。
78	type flowRequestJSON struct {
79		Entries []flowEntryJSON `json:"entries"`
80	}
81	
82	// FlowEntry 是校验通过后的一条流水。Index 是从 0 开始的输入位置。
83	type FlowEntry struct {
84		Index        int
85		Kind         string
86		ID           string
87		Account      string
88		Asset        string
89		Amount       int64
90		Fee          int64
91		Charged      int64
92		SettlementID string // 仅退款有意义
93	}
94	
95	// FieldDiff 是一个不同字段：账本值与流水值逐字并列。
96	type FieldDiff struct {
97		Field  string `json:"field"`
98		Ledger string `json:"ledger"`
99		Flow   string `json:"flow"`
100	}
101	
102	// ReconRecordRef 指向一条账本成功记录，并携带其关联记录（付款被退时的退款
103	// 编号、退款的原付款编号），使每个能定位到账本的结果都可追溯。
104	type ReconRecordRef struct {
105		Kind         string `json:"kind"`
106		ID           string `json:"id"`
107		Account      string `json:"account"`
108		Asset        string `json:"asset"`
109		Amount       int64  `json:"amount"`
110		Fee          int64  `json:"fee"`
111		Charged      int64  `json:"charged"`
112		Seq          int64  `json:"seq"`
113		SettlementID string `json:"settlement_id,omitempty"` // 退款记录：原付款编号
114		RefundID     string `json:"refund_id,omitempty"`     // 结算已被退款时：退款编号
115		RefundSeq    int64  `json:"refund_seq,omitempty"`
116	}
117	
118	// ReconResult 是一条输入流水的核对结果，顺序与输入一致。
119	type ReconResult struct {
120		Index     int             `json:"index"`
121		Kind      string          `json:"kind"`
122		ID        string          `json:"id"`
123		Status    string          `json:"status"`
124		Positions []int           `json:"positions,omitempty"` // duplicate：整组全部输入位置
125		Diffs     []FieldDiff     `json:"diffs,omitempty"`
126		Record    *ReconRecordRef `json:"record,omitempty"` // 命中账本记录时带上，可追溯关联结算/退款
127	}
128	
129	// ReconTotalRow 是一个 (账户, 资产) 组合单侧的金额汇总。金额使用十进制整数
130	// 字符串，累计可超过 int64 仍保持精确；不同资产各自一行，不相加、不抵消。
131	type ReconTotalRow struct {
132		Account       string `json:"account"`
133		Asset         string `json:"asset"`
134		ChargedTotal  string `json:"charged_total"`
135		RefundedTotal string `json:"refunded_total"`
136		NetCharged    string `json:"net_charged"`
137	}
138	
139	// ReconNetDiff 是一个组合的净扣款差额，方向为流水减账本。
140	type ReconNetDiff struct {
141		Account          string `json:"account"`
142		Asset            string `json:"asset"`
143		LedgerNetCharged string `json:"ledger_net_charged"`
144		FlowNetCharged   string `json:"flow_net_charged"`
145		NetChargedDiff   string `json:"net_charged_diff"`
146	}
147	
148	// ReconTotals 是账本侧与流水侧各自的汇总。
149	type ReconTotals struct {
150		Ledger []ReconTotalRow `json:"ledger"`
151		Flow   []ReconTotalRow `json:"flow"`
152	}
153	
154	// ReconReport 是一次对账的完整报告。
155	type ReconReport struct {
156		Results         []ReconResult    `json:"results"`
157		MissingPayments []ReconRecordRef `json:"missing_payments"`
158		MissingRefunds  []ReconRecordRef `json:"missing_refunds"`
159		Totals          ReconTotals      `json:"totals"`
160		NetDiff         []ReconNetDiff   `json:"net_diff"`
161		MaxPaymentSeq   int64            `json:"max_payment_seq"`
162		MaxRefundSeq    int64            `json:"max_refund_seq"`
163		PaymentAfter    int64            `json:"payment_after"`
164		PaymentThrough  int64            `json:"payment_through"`
165		RefundAfter     int64            `json:"refund_after"`
166		RefundThrough   int64            `json:"refund_through"`
167	}
168	
169	// ReconcileBounds 限定付款与退款各自的核对范围：每类记录只核对成功序号
170	// 满足 after < seq <= through 的记录（下界排除、上界包含）。两类记录各用
171	// 自己的序号，分别选择范围，不根据退款引用的付款序号判断退款是否入选。
172	//
173	// 指针为 nil 表示该侧不限制：下界缺省取 0，上界缺省取本次所见该类记录的
174	// 最大成功序号（即完整历史）。显式给出的上下界必须是非负 int64，且
175	// after <= through、through 不超过对应类别的最大成功序号；after == through
176	// 表示范围为空（该类记录全部不参加核对）。
177	type ReconcileBounds struct {
178		PaymentAfter   *int64
179		PaymentThrough *int64
180		RefundAfter    *int64
181		RefundThrough  *int64
182	}
183	
184	// ParseReconcileRequest 严格解析对账输入。
185	// 字段缺失、类型不符、未知 kind、数值越界或非法 JSON 均返回 invalid_parameter；
186	// 任一条目不合法则整次拒绝，不产生部分结果。
187	func ParseReconcileRequest(raw []byte) ([]FlowEntry, error) {
188		dec := json.NewDecoder(bytes.NewReader(raw))
189		var req flowRequestJSON
190		if err := dec.Decode(&req); err != nil {
191			return nil, ledgerError(ErrInvalid, "parse reconcile JSON: %v", err)
192		}
193		if tok, err := dec.Token(); err != io.EOF {
194			if err == nil {
195				return nil, ledgerError(ErrInvalid, "reconcile: unexpected trailing content after JSON document (token %v)", tok)
196			}
197			return nil, ledgerError(ErrInvalid, "reconcile: %v", err)
198		}
199		// entries 必须显式提供；{} 等缺省列表的文档视为非法输入，
200		// 只有 {"entries":[]} 才表示“空列表：全部账本记录缺失”。
201		if req.Entries == nil {
202			return nil, ledgerError(ErrInvalid, "reconcile: entries is required")
203		}
204	
205		entries := make([]FlowEntry, 0, len(req.Entries))
206		for i, e := range req.Entries {
207			at := func(msg string) error {
208				return ledgerError(ErrInvalid, "reconcile entry %d: %s", i, msg)
209			}
210			if e.Kind != "payment" && e.Kind != "refund" {
211				return nil, at(fmt.Sprintf("unknown kind %q (want payment or refund)", e.Kind))
212			}
213			if e.ID == "" {
214				return nil, at("id must not be empty")
215			}
216			if e.Account == "" {
217				return nil, at("account must not be empty")
218			}
219			if e.Asset == "" {
220				return nil, at("asset must not be empty")
221			}
222			if e.Amount == nil {
223				return nil, at("amount is required and must be an int64 integer")
224			}
225			if e.Fee == nil {
226				return nil, at("fee is required and must be an int64 integer")
227			}
228			if e.Charged == nil {
229				return nil, at("charged is required and must be an int64 integer")
230			}
231			if e.Amount.v <= 0 {
232				return nil, at("amount must be a positive int64")
233			}
234			if e.Fee.v < 0 {
235				return nil, at("fee must be a non-negative int64")
236			}
237			if e.Charged.v <= 0 {
238				return nil, at("charged must be a positive int64")
239			}
240			if e.Kind == "refund" && e.SettlementID == "" {
241				return nil, at("settlement_id must not be empty for a refund")
242			}
243			entries = append(entries, FlowEntry{
244				Index:        i,
245				Kind:         e.Kind,
246				ID:           e.ID,
247				Account:      e.Account,
248				Asset:        e.Asset,
249				Amount:       e.Amount.v,
250				Fee:          e.Fee.v,
251				Charged:      e.Charged.v,
252				SettlementID: e.SettlementID,
253			})
254		}
255		return entries, nil
256	}
257	
258	// reconSide 累计单侧（账本或流水）的金额。流水侧可能包含账本外的组合，
259	// 且累计允许超过 int64，因此一律用大整数。
260	type reconSide struct {
261		charged  map[balanceKey]*big.Int
262		refunded map[balanceKey]*big.Int
263	}
264	
265	func newReconSide() reconSide {
266		return reconSide{charged: map[balanceKey]*big.Int{}, refunded: map[balanceKey]*big.Int{}}
267	}
268	
269	func (s *reconSide) addCharged(k balanceKey, v int64) {
270		x := s.charged[k]
271		if x == nil {
272			x = new(big.Int)
273			s.charged[k] = x
274		}
275		x.Add(x, big.NewInt(v))
276	}
277	
278	func (s *reconSide) addRefund(k balanceKey, v int64) {
279		x := s.refunded[k]
280		if x == nil {
281			x = new(big.Int)
282			s.refunded[k] = x
283		}
284		x.Add(x, big.NewInt(v))
285	}
286	
287	// ReconcileFlow 对一批外部流水与当前账本状态做只读对账，核对范围为完整
288	// 历史（付款与退款都取各自全部成功记录）。等价于 ReconcileFlowRanged 传入
289	// 空边界。
290	func (l *Ledger) ReconcileFlow(entries []FlowEntry) (*ReconReport, error) {
291		return l.ReconcileFlowRanged(entries, ReconcileBounds{})
292	}
293	
294	// resolveReconRange 确定一类记录的实际核对边界 (after, through]，并校验：
295	// 边界必须非负、after 不大于 through、through 不超过该类最大成功序号。
296	// 空历史的最大序号为零，因此缺省边界为 (0,0]，范围为空。
297	func resolveReconRange(kind string, after, through *int64, maxSeq int64) (int64, int64, error) {
298		a := int64(0)
299		if after != nil {
300			a = *after
301		}
302		t := maxSeq
303		if through != nil {
304			t = *through
305		}
306		if a < 0 {
307			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: after must be a non-negative int64, got %d", kind, a)
308		}
309		if t < 0 {
310			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: through must be a non-negative int64, got %d", kind, t)
311		}
312		if a > t {
313			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: after %d must not exceed through %d", kind, a, t)
314		}
315		if t > maxSeq {
316			return 0, 0, ledgerError(ErrInvalid, "reconcile %s bounds: through %d exceeds max seq %d", kind, t, maxSeq)
317		}
318		return a, t, nil
319	}
320	
321	// ReconcileFlowRanged 对一批外部流水与当前账本状态做只读对账，只核对成功
322	// 序号落在边界内的记录（after < seq <= through）。边界不改变账本状态，
323	// 整份报告仍在同一把账本互斥锁内生成，对应同一个完整账本状态。
324	//
325	// 范围只影响记录是否参加核对，不切断关联：入选退款仍可指向范围外付款，
326	// 入选付款仍携带范围外退款的信息。命中同类型同编号但记录在范围外的流水
327	// 返回 out_of_scope（携带账本记录、不比较字段、不计入流水侧汇总）；该编号
328	// 在流水中出现多次时全部按 out_of_scope 处理。
329	func (l *Ledger) ReconcileFlowRanged(entries []FlowEntry, bounds ReconcileBounds) (*ReconReport, error) {
330		if err := l.beginOp(); err != nil {
331			return nil, err
332		}
333		defer l.endOp()
334		l.reg.mu.Lock()
335		defer l.reg.mu.Unlock()
336	
337		st := l.stateView()
338	
339		maxPay := int64(len(st.Settlements))
340		maxRef := int64(len(st.Refunds))
341		payAfter, payThrough, err := resolveReconRange("payment", bounds.PaymentAfter, bounds.PaymentThrough, maxPay)
342		if err != nil {
343			return nil, err
344		}
345		refAfter, refThrough, err := resolveReconRange("refund", bounds.RefundAfter, bounds.RefundThrough, maxRef)
346		if err != nil {
347			return nil, err
348		}
349		inPayRange := func(seq int64) bool { return seq > payAfter && seq <= payThrough }
350		inRefRange := func(seq int64) bool { return seq > refAfter && seq <= refThrough }
351	
352		// 结算编号 / 退款编号各自索引：同名编号也不会混为一笔。
353		// 关联索引始终基于完整历史：范围不切断付款与退款之间的关联。
354		payByID := make(map[string]*Record, len(st.Settlements))
355		for i := range st.Settlements {
356			payByID[st.Settlements[i].ID] = &st.Settlements[i]
357		}
358		refundByID := make(map[string]*RefundRecord, len(st.Refunds))
359		refundOfPay := make(map[string]*RefundRecord, len(st.Refunds))
360		for i := range st.Refunds {
361			r := &st.Refunds[i]
362			refundByID[r.ID] = r
363			refundOfPay[r.SettlementID] = r
364		}
365	
366		// 统计每个 (kind,id) 在输入中出现的全部位置：出现多次则整组重复，
367		// 无论内容是否相同。
368		type idUse struct{ positions []int }
369		paySeen := map[string]*idUse{}
370		refundSeen := map[string]*idUse{}
371		for i := range entries {
372			e := &entries[i]
373			m := paySeen
374			if e.Kind == "refund" {
375				m = refundSeen
376			}
377			u := m[e.ID]
378			if u == nil {
379				u = &idUse{}
380				m[e.ID] = u
381			}
382			u.positions = append(u.positions, e.Index)
383		}
384	
385		report := &ReconReport{
386			Results:         make([]ReconResult, 0, len(entries)),
387			MissingPayments: []ReconRecordRef{},
388			MissingRefunds:  []ReconRecordRef{},
389			NetDiff:         []ReconNetDiff{},
390			MaxPaymentSeq:   maxPay,
391			MaxRefundSeq:    maxRef,
392			PaymentAfter:    payAfter,
393			PaymentThrough:  payThrough,
394			RefundAfter:     refAfter,
395			RefundThrough:   refThrough,
396		}
397	
398		ledgerSide := newReconSide()
399		flowSide := newReconSide()
400		coveredPay := map[string]bool{} // 唯一且命中账本入选记录的付款编号（含字段不符）
401		coveredRefund := map[string]bool{}
402	
403		// 逐条结果（保持输入顺序）。
404		for i := range entries {
405			e := &entries[i]
406			res := ReconResult{Index: e.Index, Kind: e.Kind, ID: e.ID}
407			k := balanceKey{e.Account, e.Asset}
408	
409			uses := paySeen[e.ID]
410			var payRec *Record
411			var refRec *RefundRecord
412			inRange := false
413			if e.Kind == "payment" {
414				payRec = payByID[e.ID]
415				inRange = payRec != nil && inPayRange(payRec.Seq)
416			} else {
417				uses = refundSeen[e.ID]
418				refRec = refundByID[e.ID]
419				inRange = refRec != nil && inRefRange(refRec.Seq)
420			}
421	
422			// 1. 命中同类型同编号但记录在范围外：不比较字段、不计入流水侧汇总；
423			//    该编号在流水中出现多次时全部按 out_of_scope 处理（优先于整组重复）。
424			if (payRec != nil || refRec != nil) && !inRange {
425				res.Status = ReconOutOfScope
426				if e.Kind == "payment" {
427					ref := paymentRef(payRec, refundOfPay[e.ID])
428					res.Record = &ref
429				} else {
430					ref := refundRef(refRec)
431					res.Record = &ref
432				}
433				report.Results = append(report.Results, res)
434				continue
435			}
436	
437			// 2. 记录在范围内或账本无此编号：保留整组重复判定，流水侧合计仍包含
438			//    每一条（范围内重复项与账本外流水逐条计入）。
439			if len(uses.positions) > 1 {
440				res.Status = ReconDuplicate
441				res.Positions = append([]int(nil), uses.positions...)
442				if e.Kind == "payment" {
443					flowSide.addCharged(k, e.Charged)
444					if payRec != nil {
445						ref := paymentRef(payRec, refundOfPay[e.ID])
446						res.Record = &ref
447					}
448				} else {
449					flowSide.addRefund(k, e.Charged)
450					if refRec != nil {
451						ref := refundRef(refRec)
452						res.Record = &ref
453					}
454				}
455				report.Results = append(report.Results, res)
456				continue
457			}
458	
459			// 3. 唯一条目：命中入选记录则逐字段核对，否则账本缺这笔。
460			if e.Kind == "payment" {
461				flowSide.addCharged(k, e.Charged)
462				if payRec != nil {
463					coveredPay[e.ID] = true
464					ref := paymentRef(payRec, refundOfPay[e.ID])
465					res.Record = &ref
466					if diffs := comparePayment(payRec, e); len(diffs) > 0 {
467						res.Status = ReconFieldMismatch
468						res.Diffs = diffs
469					} else {
470						res.Status = ReconMatched
471					}
472				} else {
473					res.Status = ReconMissingInLedger
474				}
475			} else {
476				flowSide.addRefund(k, e.Charged)
477				if refRec != nil {
478					coveredRefund[e.ID] = true
479					ref := refundRef(refRec)
480					res.Record = &ref
481					if diffs := compareRefund(refRec, e); len(diffs) > 0 {
482						res.Status = ReconFieldMismatch
483						res.Diffs = diffs
484					} else {
485						res.Status = ReconMatched
486					}
487				} else {
488					res.Status = ReconMissingInLedger
489				}
490			}
491			report.Results = append(report.Results, res)
492		}
493	
494		// 账本侧合计只包含入选记录：已退款的付款仍按原扣款计入，退款单独计入
495		// 退款侧；只选退款时扣款合计为零，不会顺带计入原付款。
496		for i := range st.Settlements {
497			r := &st.Settlements[i]
498			if inPayRange(r.Seq) {
499				ledgerSide.addCharged(balanceKey{r.Account, r.Asset}, r.Charged)
500			}
501		}
502		for i := range st.Refunds {
503			r := &st.Refunds[i]
504			if inRefRange(r.Seq) {
505				ledgerSide.addRefund(balanceKey{r.Account, r.Asset}, r.Charged)
506			}
507		}
508	
509		// 入选但流水未覆盖的成功记录另列缺失（先付款后退款，各按成功顺序）。
510		// 唯一出现即算覆盖（含字段不符）；重复组对应记录按规则不列为缺失；
511		// 范围外记录不列入缺失。
512		for i := range st.Settlements {
513			r := &st.Settlements[i]
514			if !inPayRange(r.Seq) {
515				continue
516			}
517			if coveredPay[r.ID] {
518				continue
519			}
520			if u := paySeen[r.ID]; u != nil && len(u.positions) > 1 {
521				continue
522			}
523			report.MissingPayments = append(report.MissingPayments, paymentRef(r, refundOfPay[r.ID]))
524		}
525		for i := range st.Refunds {
526			r := &st.Refunds[i]
527			if !inRefRange(r.Seq) {
528				continue
529			}
530			if coveredRefund[r.ID] {
531				continue
532			}
533			if u := refundSeen[r.ID]; u != nil && len(u.positions) > 1 {
534				continue
535			}
536			report.MissingRefunds = append(report.MissingRefunds, refundRef(r))
537		}
538	
539		report.Totals = ReconTotals{
540			Ledger: buildTotalRows(ledgerSide),
541			Flow:   buildTotalRows(flowSide),
542		}
543		report.NetDiff = buildNetDiff(ledgerSide, flowSide)
544		return report, nil
545	}
546	
547	// comparePayment 比较付款的账户、资产、amount、fee、charged 五个字段。
548	func comparePayment(r *Record, e *FlowEntry) []FieldDiff {
549		var diffs []FieldDiff
550		addStr := func(field, ledger, flow string) {
551			if ledger != flow {
552				diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
553			}
554		}
555		addInt := func(field string, ledger, flow int64) {
556			if ledger != flow {
557				diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
558			}
559		}
560		addStr("account", r.Account, e.Account)
561		addStr("asset", r.Asset, e.Asset)
562		addInt("amount", r.Amount, e.Amount)
563		addInt("fee", r.Fee, e.Fee)
564		addInt("charged", r.Charged, e.Charged)
565		return diffs
566	}
567	
568	// compareRefund 比较退款的账户、资产、三个金额及原付款编号。
569	func compareRefund(r *RefundRecord, e *FlowEntry) []FieldDiff {
570		var diffs []FieldDiff
571		addStr := func(field, ledger, flow string) {
572			if ledger != flow {
573				diffs = append(diffs, FieldDiff{Field: field, Ledger: ledger, Flow: flow})
574			}
575		}
576		addInt := func(field string, ledger, flow int64) {
577			if ledger != flow {
578				diffs = append(diffs, FieldDiff{Field: field, Ledger: fmt.Sprintf("%d", ledger), Flow: fmt.Sprintf("%d", flow)})
579			}
580		}
581		addStr("account", r.Account, e.Account)
582		addStr("asset", r.Asset, e.Asset)
583		addInt("amount", r.Amount, e.Amount)
584		addInt("fee", r.Fee, e.Fee)
585		addInt("charged", r.Charged, e.Charged)
586		addStr("settlement_id", r.SettlementID, e.SettlementID)
587		return diffs
588	}
589	
590	func paymentRef(r *Record, rf *RefundRecord) ReconRecordRef {
591		ref := ReconRecordRef{
592			Kind:    "payment",
593			ID:      r.ID,
594			Account: r.Account,
595			Asset:   r.Asset,
596			Amount:  r.Amount,
597			Fee:     r.Fee,
598			Charged: r.Charged,
599			Seq:     r.Seq,
600		}
601		if rf != nil {
602			ref.RefundID = rf.ID
603			ref.RefundSeq = rf.Seq
604		}
605		return ref
606	}
607	
608	func refundRef(r *RefundRecord) ReconRecordRef {
609		return ReconRecordRef{
610			Kind:         "refund",
611			ID:           r.ID,
612			Account:      r.Account,
613			Asset:        r.Asset,
614			Amount:       r.Amount,
615			Fee:          r.Fee,
616			Charged:      r.Charged,
617			Seq:          r.Seq,
618			SettlementID: r.SettlementID,
619		}
620	}
621	
622	// sideNet 返回某组合的净扣款（扣款 - 退款）。
623	func sideNet(side reconSide, k balanceKey) *big.Int {
624		charged := new(big.Int)
625		if x := side.charged[k]; x != nil {
626			charged.Set(x)
627		}
628		refunded := new(big.Int)
629		if x := side.refunded[k]; x != nil {
630			refunded.Set(x)
631		}
632		return charged.Sub(charged, refunded)
633	}
634	
635	func allKeys(a, b reconSide) []balanceKey {
636		seen := map[balanceKey]bool{}
637		var keys []balanceKey
638		add := func(m map[balanceKey]*big.Int) {
639			for k := range m {
640				if !seen[k] {
641					seen[k] = true
642					keys = append(keys, k)
643				}
644			}
645		}
646		add(a.charged)
647		add(a.refunded)
648		add(b.charged)
649		add(b.refunded)
650		sort.Slice(keys, func(i, j int) bool {
651			if keys[i].account != keys[j].account {
652				return keys[i].account < keys[j].account
653			}
654			return keys[i].asset < keys[j].asset
655		})
656		return keys
657	}
658	
659	// buildTotalRows 按账户、资产排序输出单侧汇总；净扣款 = 扣款 - 退款。
660	func buildTotalRows(side reconSide) []ReconTotalRow {
661		keys := allKeys(side, reconSide{})
662		out := make([]ReconTotalRow, 0, len(keys))
663		for _, k := range keys {
664			charged := new(big.Int)
665			if x := side.charged[k]; x != nil {
666				charged.Set(x)
667			}
668			refunded := new(big.Int)
669			if x := side.refunded[k]; x != nil {
670				refunded.Set(x)
671			}
672			net := new(big.Int).Sub(new(big.Int).Set(charged), refunded)
673			out = append(out, ReconTotalRow{
674				Account:       k.account,
675				Asset:         k.asset,
676				ChargedTotal:  charged.String(),
677				RefundedTotal: refunded.String(),
678				NetCharged:    net.String(),
679			})
680		}
681		return out
682	}
683	
684	// buildNetDiff 输出每个（任一侧出现过的）组合的净扣款差额，方向为流水减账本。
685	func buildNetDiff(ledger, flow reconSide) []ReconNetDiff {
686		out := make([]ReconNetDiff, 0)
687		for _, k := range allKeys(ledger, flow) {
688			lNet := sideNet(ledger, k)
689			fNet := sideNet(flow, k)
690			diff := new(big.Int).Sub(new(big.Int).Set(fNet), lNet)
691			out = append(out, ReconNetDiff{
692				Account:          k.account,
693				Asset:            k.asset,
694				LedgerNetCharged: lNet.String(),
695				FlowNetCharged:   fNet.String(),
696				NetChargedDiff:   diff.String(),
697			})
698		}
699		return out
700	}
701

